#!/bin/bash
set -euo pipefail
app_name='';app_uuid=''
while getopts ':i:n:s:' opt; do
 case "$opt" in i) app_uuid="$OPTARG" ;; n|s) app_name="$OPTARG" ;; *) exit 64 ;; esac
done
[[ "$(id -un)" == 'emprendeclaro' ]] || exit 77
[[ "$app_name" == 'emprendeclaro_mobile_fix_v2' ]] || exit 64
[[ "$(pwd -P)" == '/home/emprendeclaro/apps/emprendeclaro_mobile_fix_v2' ]] || exit 77
umask 077
/usr/local/bin/python3.11 - "$app_uuid" <<'PATCH'
import base64,hashlib,json,os,pathlib,re,sys,urllib.request
app_id=sys.argv[1]
if not re.fullmatch(r'[0-9a-f-]{36}',app_id):raise SystemExit('Invalid app identifier')
if os.environ.get('API_URL','').replace('https://','').rstrip('/')!='my.opalstack.com':raise SystemExit('Unexpected API origin')
p=pathlib.Path('/home/emprendeclaro/apps/emprendeclaro_demo_v2/styles.css')
if p.is_symlink() or hashlib.sha256(p.read_bytes()).hexdigest()!='3d59de7a64319fe9f9027bc8073b61c4532c485c248512e4676aae3418737828':raise SystemExit('Styles changed; patch aborted')
payload=base64.b64decode('')
if hashlib.sha256(payload).hexdigest()!='c3a6f02882aea8a1b77925e2b4db0767dcc1e2bb5228d095003233f6e92b48b2':raise SystemExit('Patch checksum mismatch')
tmp=p.with_name('styles.mobile-v2.tmp')
if tmp.exists() or tmp.is_symlink():raise SystemExit('Temporary file already exists')
with tmp.open('xb') as f:f.write(payload)
tmp.chmod(0o644);tmp.replace(p)
token=os.environ.get('OPAL_TOKEN','')
if not token:raise SystemExit('Missing installer authorization')
request=urllib.request.Request('https://my.opalstack.com/api/v1/app/installed/',data=json.dumps([{'id':app_id}]).encode(),headers={'Authorization':'Token '+token,'Content-Type':'application/json'},method='POST')
with urllib.request.urlopen(request,timeout=30) as response:response.read()
print('Narrow mobile header patch applied only to EmprendeClaro.')
PATCH
